; ========================================================================
; DMPRTSEL.ACC -- Fully Annotated Disassembly
; DeskMate 3.05, Tandy Corporation, Copyright (c) 1987, Microsoft Corp.
; Compiled with Microsoft C 5.x (1987), Medium Memory Model
; Annotated for the Bayside reverse engineering project
; ========================================================================
;
; DMPRTSEL.ACC is the printer selector -- ui for choosing and configuring printers.
; DMPRTSEL.ACC is the printer selector accessory for DeskMate 3.05. It
; provides a user interface for choosing which printer driver to use and
; configuring printer ports.
;
; Imports PRGUF (not DMGUF like most ACCs) for UI rendering. Uses
; INT 11h (BIOS equipment list) and INT 13h (disk services) for
; hardware detection, likely to enumerate available printer ports.
;
; Configuration is stored in DMPRTSEL.CFG. The module supports
; "Get a new list of printers" for rescanning available drivers.
;
; ========================================================================
; BINARY STRUCTURE
; ========================================================================
;
; MZ + DM89 header (512 bytes)
; File size: 13,643 bytes
; Load image: 13,131 bytes (after header)
; DM89 entry point: 027A:0006 (MSC 5.x CRT startup)
; SS:SP = 0676:0FA0
;
; Segment Map (5 segments, 14 relocations):
;   seg_0000     CODE     Printer selector application code + PRGUF thunks
;   seg_027A     CODE     MSC 5.x CRT startup
;   seg_0285     CODE     DM89 import far-call dispatcher
;   seg_0289     DATA     DGROUP -- printer lists, port config, strings
;   seg_0676     STACK    Stack segment
;
; Medium memory model: multiple code segments, DGROUP at 0289.
;
; DM flags: 0x0000
; Imports: PRGUF
;
; ========================================================================
; INTERRUPT SERVICES USED
; ========================================================================
;
; INT E0h (DeskMate API):
;   AH=00h (Core services)
;   AH=02h (Resource/UI services)
;   AH=06h (Window/event services)
;   AH=07h (Memory services)
;
; INT 21h (DOS API):
;   AH=25h (Set interrupt vector)
;   AH=30h (Get DOS version)
;   AH=35h (Get interrupt vector)
;   AH=3Eh (Close file)
;   AH=40h (Write file)
;   AH=44h (IOCTL)
;   AH=4Ah (Resize memory block)
;   AH=4Ch (Exit process)
;
; Other interrupts:
;   INT 11h x1 (BIOS equipment list)
;   INT 13h x2 (Disk services)
;   INT 20h x1 (DOS terminate)
;
; ========================================================================
; NOTABLE STRINGS
; ========================================================================
;
;   "DMSETUP"  -- Setup module reference
;   "DMPRTSEL.CFG"  -- Printer selection configuration file
;   "DMPD.CFG"  -- Printer driver configuration
;   "INSTALL.CFG"  -- Installation configuration
;   "Printers"  -- Printer list window title
;   "No printer"  -- No printer selected option
;   "Printer Ports"  -- Port selection dialog title
;   "Get a new list of printers"  -- Rescan printers button label
;
; ========================================================================
; FUNCTION INDEX (130 functions total)
; ========================================================================
;
; --- DMPRTSEL Application Functions ---
;
; Address   Name                          Size  Description
; -------   ----                          ----  -----------
; 0000:0010 dmprtsel_main                    77  Main entry -- init printer selector
; 0000:0085 dmprtsel_showPrinterList        267  Display printer selection list
; 0000:0190 dmprtsel_selectPrinter          334  Handle printer selection
; 0000:02DE dmprtsel_showPortList           113  Show printer port selection dialog
; 0000:034F dmprtsel_scanPrinters           231  Scan for available printer drivers
; 0000:0436 dmprtsel_configPrinter          298  Configure selected printer settings
; 0000:0646 dmprtsel_saveConfig             161  Save printer selection to DMPRTSEL.CFG
